export function initEditions({db,esc,date,getArticles,openNews}){
 const root=document.createElement('section');root.className='personal-editions';document.querySelector('#feed>.heading').after(root);
 let user=null,prefs={times:['07:30','13:00','21:00'],interests:'',use_interactions:true,alerts:false},current=null,epoch=0;const labels=['Mañana','Mediodía','Noche'];
 const dialog=document.createElement('dialog');dialog.className='poll-dialog';document.body.append(dialog);
 const chile=()=>Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Santiago',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).map(p=>[p.type,p.value]));
 function slot(){const d=chile(),t=d.hour+':'+d.minute;return {day:d.year+'-'+d.month+'-'+d.day,index:prefs.times.reduce((n,x,i)=>x<=t?i:n,-1)};}
 function render(){root.innerHTML='<span class="eyebrow">TU DÍA, CON CONTEXTO</span><h2>Tus tres ediciones</h2><div class="edition-tabs">'+labels.map((l,i)=>'<button data-edition="'+i+'">'+l+' · '+esc(prefs.times[i])+'</button>').join('')+'</div><p>Selección de noticias con síntesis y fuentes. Hora de Chile.</p><button id="edition-settings">Ajustar horarios e intereses</button><p id="edition-status" role="status"></p>';root.querySelectorAll('[data-edition]').forEach(b=>b.onclick=()=>open(Number(b.dataset.edition)));root.querySelector('#edition-settings').onclick=settings;}
 async function open(index){if(!user){root.querySelector('#edition-status').textContent='Ingresa con Convergencia para guardar tus ediciones.';return;}const token=epoch,s=slot();if(index>s.index){root.querySelector('#edition-status').textContent='Esta edición estará disponible a las '+prefs.times[index]+'.';return;}const key=s.day+'/'+index;const owner=user.id;const saved=await db.from('atlas_dev_editions').select('*').eq('user_id',owner).eq('edition_key',key).maybeSingle();if(token!==epoch)return;if(saved.error){root.querySelector('#edition-status').textContent='No se pudo consultar la edición. Reintenta.';return;}current=saved.data;
 if(!current){let follows=[],likes=[];if(prefs.use_interactions){const [f,l]=await Promise.all([db.from('atlas_dev_news_follows').select('value').eq('user_id',owner),db.from('atlas_dev_news_likes').select('article_id').eq('user_id',owner).limit(100)]);follows=f.data||[];likes=l.data||[];}if(token!==epoch)return;const words=(prefs.interests+' '+follows.map(f=>f.value).join(' ')).toLocaleLowerCase().split(/[,;\s]+/).filter(w=>w.length>2);const articles=getArticles().filter(a=>a.reading?.status==='ready'&&a.reading.context?.length);const scored=articles.map(a=>({a,score:words.reduce((n,w)=>n+(JSON.stringify([a.title,a.topics]).toLocaleLowerCase().includes(w)?1:0),0)+(likes.some(l=>l.article_id===a.id)?1:0)})).sort((a,b)=>b.score-a.score||Date.parse(b.a.publishedAt)-Date.parse(a.a.publishedAt));const seen=new Set();const chosen=scored.filter(({a})=>{const k=a.coverage?.id||a.id;if(seen.has(k))return false;seen.add(k);return true;}).slice(0,5).map(x=>x.a);if(!chosen.length){root.querySelector('#edition-status').textContent='La edición se está preparando con noticias verificables. Reintenta cuando haya síntesis disponibles.';return;}const row={user_id:owner,edition_key:key,body:{label:labels[index],articles:chosen}};const insert=await db.from('atlas_dev_editions').upsert(row,{onConflict:'user_id,edition_key',ignoreDuplicates:true}).select().maybeSingle();if(token!==epoch)return;if(insert.error){root.querySelector('#edition-status').textContent='No se pudo guardar la edición.';return;}current=insert.data|| (await db.from('atlas_dev_editions').select('*').eq('user_id',owner).eq('edition_key',key).single()).data;}
 if(token!==epoch||!current)return;draw();}
 function draw(){const row=current;dialog.innerHTML='<button id="edition-close" aria-label="Cerrar edición">×</button><span class="eyebrow">EDICIÓN PERSONAL · '+esc(row.body.label)+'</span><h2>Tu día, con contexto.</h2><p>'+esc(date(row.created_at))+'</p>'+row.body.articles.map((a,i)=>'<article><h3><button data-edition-read="'+i+'">'+esc(a.title)+'</button></h3>'+['what','change','background','next'].map(k=>(a.reading[k]||[]).map(p=>{const source=a.reading.sources?.find(s=>s.id===(p.source||1));return '<p>'+esc(p.text)+(source? ' <a href="'+esc(source.url)+'" target="_blank" rel="noopener noreferrer">'+esc(source.name)+' ↗</a>':'')+'</p>';}).join('')).join('')+'</article>').join('')+'<form id="edition-feedback"><h3>¿Qué tan útil fue esta edición?</h3><fieldset><legend>Califica de 1 a 5 estrellas</legend>'+[1,2,3,4,5].map(n=>'<label style="display:inline-block;margin:6px"><input type="radio" name="stars" value="'+n+'" '+(row.rating===n?'checked':'')+'> '+n+' ★</label>').join('')+'</fieldset><label>¿Qué mejorarías? (opcional)<textarea name="feedback" maxlength="1500">'+esc(row.feedback||'')+'</textarea></label><button>Guardar evaluación</button><button type="button" id="edition-skip">Omitir y cerrar</button><p id="edition-feedback-status" role="status"></p></form>';dialog.querySelector('#edition-close').onclick=()=>dialog.close();dialog.querySelector('#edition-skip').onclick=()=>dialog.close();dialog.querySelectorAll('[data-edition-read]').forEach(b=>b.onclick=()=>{dialog.close();openNews(row.body.articles[Number(b.dataset.editionRead)]);});dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target),rating=Number(data.get('stars'))||null,feedback=String(data.get('feedback')||'');const owner=user?.id;if(!owner)return;const {error}=await db.from('atlas_dev_editions').update({rating,feedback}).eq('user_id',owner).eq('edition_key',row.edition_key);dialog.querySelector('#edition-feedback-status').textContent=error?'No se pudo guardar. Reintenta.':'Gracias. Tu evaluación quedó guardada.';};if(!dialog.open)dialog.showModal();}
 function settings(){dialog.innerHTML='<button id="edition-close">Cerrar</button><h2>Tus ediciones</h2><form>'+labels.map((l,i)=>'<label>'+l+'<input type="time" name="time'+i+'" value="'+prefs.times[i]+'" required></label>').join('')+'<label>Temas y lugares de interés<input name="interests" maxlength="500" value="'+esc(prefs.interests)+'" placeholder="Chile, clima, ciencia"></label><label><input type="checkbox" name="interactions" '+(prefs.use_interactions?'checked':'')+'> Usar temas seguidos y likes en Atlas</label><label><input type="checkbox" name="alerts" '+(prefs.alerts?'checked':'')+'> Avisarme con Atlas abierto</label><p>Los avisos se comprueban mientras Atlas está abierto. Las notificaciones con la aplicación cerrada aún no están habilitadas.</p><button>Guardar preferencias</button><p role="status" id="edition-save-status"></p></form>';dialog.querySelector('#edition-close').onclick=()=>dialog.close();dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();if(!user){dialog.querySelector('#edition-save-status').textContent='Ingresa con Convergencia.';return;}const f=new FormData(e.target),times=[0,1,2].map(i=>f.get('time'+i));if(times.some((t,i)=>i&&t<=times[i-1])){dialog.querySelector('#edition-save-status').textContent='Ordena los horarios de mañana a noche.';return;}const next={times,interests:f.get('interests'),use_interactions:f.has('interactions'),alerts:f.has('alerts')};const {error}=await db.from('atlas_dev_edition_preferences').upsert({user_id:user.id,...next});if(error){dialog.querySelector('#edition-save-status').textContent='No se pudo guardar.';return;}prefs=next;dialog.close();render();};dialog.showModal();}
 const notified=new Set();setInterval(()=>{if(!user||!prefs.alerts)return;const s=slot(),key=s.day+'/'+s.index;if(s.index<0||notified.has(key))return;notified.add(key);const b=document.createElement('button');b.className='edition-alert';b.textContent='Tu edición de '+labels[s.index].toLocaleLowerCase()+' · Abrir resumen';b.onclick=()=>{open(s.index);b.remove();};root.prepend(b);},30000);
 async function auth(session){epoch++;user=session?.user||null;current=null;dialog.close();prefs={times:['07:30','13:00','21:00'],interests:'',use_interactions:true,alerts:false};const token=epoch;if(user){const r=await db.from('atlas_dev_edition_preferences').select('*').eq('user_id',user.id).maybeSingle();if(token!==epoch)return;if(r.data)prefs=r.data;}render();}
 render();db?.auth.getSession().then(({data})=>auth(data.session));db?.auth.onAuthStateChange((e,s)=>setTimeout(()=>auth(s),0));
}